package cue

import (
	_ \"embed\"
	\"encoding/json\"
	\"errors\"
	\"fmt\"
	\"io\"
	\"os\"
	\"strconv\"
	\"strings\"

	\"cuelang.org/go/cue\"
	\"cuelang.org/go/cue/cuecontext\"
	cueerror \"cuelang.org/go/cue/errors\"
	\"cuelang.org/go/encoding/yaml\"
	yamlv3 \"gopkg.in/yaml.v3\"
)

const (
	jsonFormat = \"json\"
	textFormat = \"text\"
)

var (
	//go:embed flipt.cue
	cueFile             []byte
	ErrValidationFailed = errors.New(\"validation failed\")
)

// Result collects all errors found while validating a YAML document.
type Result struct {
	Errors []Error "'`json:"errors"`
}

// FeaturesValidator holds the compiled features schema.
type FeaturesValidator struct {
	cue *cue.Context
	v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return nil, err
	}
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// ValidateBytes validates YAML against the features schema.
func ValidateBytes(b []byte) error {
	cctx := cuecontext.New()
	return validate(b, cctx)
}

// validate retains the raw CUE error for existing callers.
func validate(b []byte, cctx *cue.Context) error {
	v := cctx.CompileBytes(cueFile)
	if err := v.Err(); err != nil {
		return err
	}
	f, err := yaml.Extract("", b)
	if err != nil {
		return err
	}
	return v.Unify(cctx.BuildFile(f, cue.Scope(v))).Validate()
}

// Location identifies a position in the original YAML document.
type Location struct {
	File   string `json:"file,omitempty"`
	Line   int    `json:"line"`
	Column int    `json:"column"`
}

// Error describes a validation failure and the field that caused it.
type Error struct {
	Path     string   `json:"path"`
	Message  string   `json:"message"`
	Location Location `json:"location"`
}

// Validate returns every validation error in the document.
func (fv *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
	result := Result{Errors: make([]Error, 0)}
	f, err := yaml.Extract(file, b)
	if err == nil {
		yv := fv.cue.BuildFile(f, cue.Scope(fv.v))
		err = fv.v.Unify(yv).Validate()
	}
	if err == nil {
		return result, nil
	}

	positions := yamlFieldPositions(file, b)
	for _, ce := range cueerror.Errors(err) {
		path := strings.Join(ce.Path(), ".")
		format, args := ce.Msg()
		message := fmt.Sprintf(format, args...)
		if path != "" {
			message = path + ": " + message
		}
		location, ok := positions[path]
		if !ok {
			location = cueLocation(file, ce)
		}
		result.Errors = append(result.Errors, Error{Path: path, Message: message, Location: location})
	}
	if len(result.Errors) == 0 {
		result.Errors = append(result.Errors, Error{Message: err.Error(), Location: Location{File: file}})
	}
	return result, ErrValidationFailed
}

// yamlFieldPositions records the location of each mapping key. CUE'"'s input
// positions can include positions from the schema and from the field value.
func yamlFieldPositions(file string, b []byte) map[string]Location {
	positions := make(map[string]Location)
	var document yamlv3.Node
	if err := yamlv3.Unmarshal(b, &document); err "'!= nil {
		return positions
	}
	var walk func(*yamlv3.Node, string)
	walk = func(node *yamlv3.Node, path string) {
		switch node.Kind {
		case yamlv3.DocumentNode:
			for _, child := range node.Content {
				walk(child, path)
			}
		case yamlv3.MappingNode:
			for i := 0; i+1 < len(node.Content); i += 2 {
				key, value := node.Content[i], node.Content[i+1]
				childPath := key.Value
				if path != "" {
					childPath = path + "." + childPath
				}
				positions[childPath] = Location{File: file, Line: key.Line, Column: key.Column}
				walk(value, childPath)
			}
		case yamlv3.SequenceNode:
			for i, child := range node.Content {
				childPath := strconv.Itoa(i)
				if path != "" {
					childPath = path + "." + childPath
				}
				positions[childPath] = Location{File: file, Line: child.Line, Column: child.Column}
				walk(child, childPath)
			}
		}
	}
	walk(&document, "")
	return positions
}

func cueLocation(file string, ce cueerror.Error) Location {
	location := Location{File: file}
	for _, pos := range ce.InputPositions() {
		if pos.IsValid() && (pos.Filename() == file || file == "" && pos.Filename() == "") {
			location.Line, location.Column = pos.Line(), pos.Column()
			return location
		}
	}
	pos := ce.Position()
	if pos.IsValid() && pos.Filename() == file {
		location.Line, location.Column = pos.Line(), pos.Column()
	}
	return location
}

func writeErrorDetails(format string, result Result, w io.Writer) error {
	switch format {
	case jsonFormat:
		return json.NewEncoder(w).Encode(result)
	case textFormat:
		// Use the text layout below.
	default:
		if _, err := fmt.Fprintln(w, "Invalid format chosen, defaulting to '"\\\"text\\\" format...\"); err "'!= nil {
			return err
		}
	}
	if _, err := fmt.Fprintln(w, "❌ Validation failure!"); err != nil {
		return err
	}
	for _, e := range result.Errors {
		if _, err := fmt.Fprintf(w, "'"\\n- %s:%d:%d: %s\\n\", e.Location.File, e.Location.Line, e.Location.Column, e.Message); err "'!= nil {
			return err
		}
	}
	return nil
}

// ValidateFiles validates files and writes all errors in the requested format.
func ValidateFiles(dst io.Writer, files []string, format string) error {
	validator, err := NewFeaturesValidator()
	if err != nil {
		return err
	}
	result := Result{Errors: make([]Error, 0)}
	for _, file := range files {
		b, err := os.ReadFile(file)
		if err != nil {
			return fmt.Errorf("read %s: %w", file, err)
		}
		fileResult, _ := validator.Validate(file, b)
		result.Errors = append(result.Errors, fileResult.Errors...)
	}
	if len(result.Errors) > 0 {
		if err := writeErrorDetails(format, result, dst); err != nil {
			return err
		}
		return ErrValidationFailed
	}
	if format == jsonFormat {
		return nil
	}
	if format != textFormat {
		if _, err := fmt.Fprintln(dst, "Invalid format chosen, defaulting to '"\\\"text\\\" format...\"); err "'!= nil {
			return err
		}
	}
	_, err = fmt.Fprintln(dst, "✅ Validation success!")
	return err
}
EOF
